ee:message.ee:set-payload:
%dw 2.0
output application/json

import modules::GlobalFunctions as global
import fail from dw::Runtime

var idIntento = uuid()

var ahora = global::fechaMongo()

var caracteristicasOrden =
    if (vars.requestOrder.category == "LTE") vars.objectOrden.Caracteristicas_Orden
    else vars.objectOrden.Caracteristica_Orden

var emailNotificacion = global::valorCaracteristica(caracteristicasOrden, "CORREO_NOTIFICACION_CANCELACION")

var cli   = vars.objectCliente_Tramite.Cliente_Tramite

// ---------- FTTH ----------
fun datosFTTH(src) = 
   { srv: {
	    fechaActivacion: src.Fecha_Activacion,          
	    ctaServicio:     src.Id_Cuenta_Servicio,          
	    ctaFacturacion:  src.Id_Cuenta_Facturacion,  
	    estado: src.Estado.Principal.Descripcion,     
	    producto: [{
	        idBundle:   src.Bundle.Numero_Agrupacion,
	        idAuxiliar: (src.Servicios_Auxiliares default []) map (aux) -> { id: aux.Bundle.Numero_Agrupacion },
	        svaOtt:     (src.Opcionales default []) map (o) -> { id: o.Codigo_Configuracion }
	    }]
    },
    canc: {
        idBundle:        vars.objectOrden.Servicio_Tramite.Bundle.Numero_Agrupacion,        
        idAuxiliar: (vars.objectOrden.Servicio_Tramite.Servicios_Auxiliares default []) map (aux) -> { id: aux.Bundle.Numero_Agrupacion },
        svaOtt:     (vars.objectOrden.Servicio_Tramite.Opcionales default []) map (o) -> { id: o.Codigo_Configuracion },              
        numeroOrden:     vars.objectOrden.Numero_Orden,                  
        cuentaServicio:  src.Id_Cuenta_Servicio,         
        fechaProgramada: vars.objectOrden.Tramite.Fecha_Ejecucion,        
        tecnologia:      "FTTH"
    }
}

// ---------- LTE ----------
fun datosLTE(src) = 
   { srv: {
    fechaActivacion: src.Fecha_Activacion,                
    ctaServicio:     "",                   
    ctaFacturacion:  src.Cuenta_Facturacion,
    estado: src.Estado,                         
    producto: (src.Bundles default []) map (pl) -> {
        idBundle:   pl.id_catalogo,                     
        idAuxiliar: null,
        svaOtt:     []
      }
    },
    canc: {
        idBundle:        vars.objectOrden.Bundle_activo[0].id_catalogo,        
        idAuxiliar: (vars.objectOrden.Bundle_activo[0].bundle_auxiliar default []) map (aux) -> { id: aux.id_catalogo },
        svaOtt:     (vars.objectOrden.Bundle_activo[0].opcionales default []) map (o) -> { id: o.id_opcional },              
        numeroOrden:     vars.objectOrden.Numero_Orden,                  
        cuentaServicio:  "",         
        fechaProgramada: global::parseFechaFlexible(global::valorCaracteristica(vars.objectOrden.Caracteristicas_Orden, "Fecha Vencimiento")),        
        tecnologia:      "LTE"
    }
}


var datos = vars.requestOrder.category match {
    case "FTTH" -> datosFTTH(vars.objectServicio_Tramite)         
    case "LTE"  -> datosLTE(vars.objectServicioActivo)           
    else        -> fail("Categoria no soportada para journey: " ++ vars.requestOrder.category)
}

var srv  = datos.srv
var canc = datos.canc

var canal = vars.requestOrder.channel
var filtro = {
        "cliente.tipoDocumento":   cli.Tipo_Documento,
        "cliente.numeroDocumento": cli.Numero_Documento as String,
        "tramitesComerciales.cancelacion.idIntento": { "\$ne": idIntento }
}

var update = {
        "\$setOnInsert": {
            "cliente.correoUsuario": cli.Email,

            fechaRegistro: ahora,
            "tramitesComerciales.activacion":   [],
            "tramitesComerciales.cambioPlan":   [],
            "tramitesComerciales.fidelizacion": [],
            "tramitesComerciales.retencion":    []
        },

        "\$set": {
            fechaModificacion: ahora,
            "cliente.correoNotificacion": emailNotificacion,
		    ("servicioVigente.fechaActivacion": { "\$date": srv.fechaActivacion }) if (srv.fechaActivacion != null),
		    ("servicioVigente.cuentaServicio":     srv.ctaServicio)                   if (srv.ctaServicio != null),
		    ("servicioVigente.cuentaFacturacion":  srv.ctaFacturacion)                if (srv.ctaFacturacion != null),
		    "servicioVigente.ultimoTramite":    "",
		    "servicioVigente.estado":           srv.estado
        },


        "\$push": {
            "servicioVigente.producto": {
                "\$each": (srv.producto default []) map (prod) -> {
                    idBundle:   prod.idBundle as Number,
                    idAuxiliar: (prod.idAuxiliar default []) map (sva) -> { id: sva.id as Number },
                    svaOtt:     (prod.svaOtt default []) map (sva) -> { id: sva.id as Number }
                }
            },
            "tramitesComerciales.cancelacion": {
			    idIntento:          idIntento,
			    (idBundle:          canc.idBundle)       if (canc.idBundle != null),
			    idAuxiliar: (canc.idAuxiliar default []) map (sva) -> { id: sva.id as Number },
                svaOtt:     (canc.svaOtt default []) map (sva) -> { id: sva.id as Number },
			    numeroOrden:        canc.numeroOrden,
			    (cuentaServicio:    canc.cuentaServicio) if (canc.cuentaServicio != null),
			    fechaRegistro:      ahora,
			    fechaProgramada:    canc.fechaProgramada,
			    fechaEjecucion:     null,
			    fechaDesactivacion: null,
			    estado:             "PENDIENTE",
			    tecnologia:         canc.tecnologia,
			    canal:              canal,
			    resultado:          "PENDIENTE"
			},
            interacciones: {
                tipoInteraccion:    "REGISTRO ORDEN CANCELACION",
                detalleInteraccion: "Se crea orden cancelacion cuenta servicio: " ++ (canc.cuentaServicio default ""),
                canal:              canal,
                correlationId:      vars.headers."X-CORRELATION-ID",
                fechaInteraccion:   ahora
            },
            auditoria: {
                tramite:           "CANCELACION SERVICIO",
                fechaRegistro:     ahora,
                fechaModificacion: ahora,
                aplicacion:        canal
            }
        }
    }
---
{
    query: {
        update:  p('mongo-db-sapi.collections.journey'),
        updates: [
            {
                q:      filtro,
                u:      update,
                upsert: true,
                multi:  false
            }
        ]
    }
}

ee:variables.ee:set-variable:
%dw 2.0
output application/java
var body = if (payload is String) read(payload, "application/json") else payload
var res  = body.result default {}
var we   = (res.writeErrors default [])[0]
var cod  = (body.codigo default "200") as String
---
if (cod startsWith "5")
    { estado: "REINTENTAR", detalle: "SAPI codigo " ++ cod ++ ": " ++ (body.mensaje default "") }
else if (not (cod startsWith "2"))
    { estado: "INVALIDO", detalle: "SAPI codigo " ++ cod ++ ": " ++ (body.mensaje default "") }
else if (we == null and (res.ok default 0) == 1)
    { estado: "OK", detalle: null }
else if (we != null and we.code == 11000 and ((we.errmsg default "") contains p('journey.mongo.uniqueIndex')))
    { estado: "DUPLICADO_POSIBLE", detalle: we.errmsg }
else if (we != null and we.code == 121)
    { estado: "INVALIDO", detalle: "121: " ++ (we.errmsg default "") ++ " | errInfo: " ++ write(we.errInfo default {}, "application/json", { indent: false }) }
else
    { estado: "REINTENTAR", detalle: if (we != null) ((we.code default "") as String ++ ": " ++ (we.errmsg default "")) else "Respuesta sin ok=1" }
